using Serilog;

var builder = WebApplication.CreateBuilder(args);

// Serilog is configured from the "Serilog" section of appsettings (levels, sinks, properties).
builder.Services.AddSerilog((services, config) => config
    .ReadFrom.Configuration(builder.Configuration)
    .ReadFrom.Services(services)
    .Enrich.FromLogContext());

builder.Services.AddControllers();
builder.Services.AddOpenApi();
builder.Services.AddHealthChecks();

var app = builder.Build();

if (app.Environment.IsDevelopment())
{
    // The OpenAPI document is generated by the built-in Microsoft.AspNetCore.OpenApi (/openapi/v1.json).
    // Swagger UI only displays it, so the SwaggerUI package is enough (no SwaggerGen needed).
    app.MapOpenApi();
    app.UseSwaggerUI(options => options.SwaggerEndpoint("/openapi/v1.json", "PulseWallet API v1"));  // UI at /swagger
}

app.UseSerilogRequestLogging();
app.UseAuthorization();
app.MapControllers();
app.MapHealthChecks("/health");

app.Run();